head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.onpageload = function() {
    scwin.createWindow();
};
scwin.onpageunload = function() {};
scwin.createWindow = function() {
    var c_cnt = 3;
    var c_subName = "sub";
    var c_menuName = "menu";
    for (var i = 0; i < c_cnt; i++) {
        var winObj = {
            title: c_subName + i,
            src: "sub.xml",
            windowId: c_menuName + i
        }
        windowContainer1.createWindow(winObj);
    }
};
scwin.trigger1_onclick = function() {
    var idStr = windowContainer1.windows[windowContainer1.getSelectedIndex()].id;
    input1.setValue(idStr);
};
scwin.checkVal = function() {
    return scwin.__getDom($p.id + 'windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow_menu0_1') != null
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
}
